import {chapterFourActor,C4_STATS} from './chapter-four-models.js';
import * as T from './vendor/three.module.js';
import {citizenModel} from './chapter-two-models.js';
import {beastModel} from './chapter-two-wildlife.js';
export const C3_STATS={...C4_STATS,soldier:{hp:180,damage:24,level:17},marksman:{hp:155,damage:22,level:18},cantor:{hp:165,damage:20,level:18},hound:{hp:190,damage:25,level:18},gargoyle:{hp:230,damage:26,level:19},knight:{hp:310,damage:29,level:20},captain:{hp:420,damage:25,level:20},baron:{hp:1350,damage:32,level:23}};
export function chapterThreeActor(parent,role,x,z,palette,id){if(C4_STATS[role])return chapterFourActor(parent,role,x,z,palette,id);
 const base=role==='hound'?beastModel(parent,'wolf',x,z):citizenModel(parent,x,z,{id,role:['marksman','captain'].includes(role)?'crossbow':role==='cantor'?'mage':role==='baron'?'vampire':'sword',cloth:role==='baron'?4:role==='cantor'?10:7,skin:role==='baron'?1:0,scale:role==='baron'?1.3:role==='knight'?1.13:1},palette);
 const g=base.g;g.userData.dynamic=true;const metal=palette.material(8,0x8b9aa8),stone=palette.material(15,0x768593),blood=new T.MeshBasicMaterial({color:0xcc315a});const add=(geo,mat,x,y,z)=>{const m=new T.Mesh(geo,mat);m.position.set(x,y,z);g.add(m);return m};let wings=[],shield;
 if(['knight','captain','baron'].includes(role)){add(new T.SphereGeometry(.23,10,8),metal,0,1.9,0).scale.set(1,.65,1);for(const side of [-1,1])add(new T.SphereGeometry(.2,10,8),metal,side*.32,1.45,0);shield=add(new T.CylinderGeometry(.37,.37,.1,8),metal,-.49,1.16,.15);shield.rotation.x=Math.PI/2;add(new T.BoxGeometry(.11,.6,.12),palette.material(4),-.49,1.16,.23)}
 if(role==='gargoyle'||role==='baron'){for(const side of [-1,1]){const pivot=new T.Group();pivot.position.set(side*.25,1.35,-.15);g.add(pivot);const geo=new T.BufferGeometry().setFromPoints([new T.Vector3(),new T.Vector3(side*1.5,.7,-.25),new T.Vector3(side*1.1,-.45,-.4),new T.Vector3(side*.4,-.65,-.1)]);geo.setIndex([0,1,2,0,2,3]);geo.computeVertexNormals();pivot.add(new T.Mesh(geo,new T.MeshStandardMaterial({color:role==='gargoyle'?0x6c7c83:0x4d182c,side:T.DoubleSide,roughness:1})));wings.push(pivot)}if(role==='gargoyle')g.traverse(o=>{if(o.isMesh&&!wings.includes(o.parent))o.material=stone});if(role==='gargoyle')for(const side of [-1,1]){add(new T.SphereGeometry(.027,6,5),new T.MeshBasicMaterial({color:0x9ee8fa}),side*.065,1.79,.18);add(new T.ConeGeometry(.06,.28,6),stone,side*.16,2.05,0)}}
 if(role==='hound'){g.scale.setScalar(1.13);add(new T.TorusGeometry(.32,.055,6,12),metal,0,.85,.45).rotation.x=Math.PI/2;for(const side of [-1,1])add(new T.SphereGeometry(.045,6,5),blood,side*.12,1.12,.97)}
 if(role==='cantor'){const ring=add(new T.TorusGeometry(.7,.045,6,28),new T.MeshBasicMaterial({color:0x74e4b1}),0,.2,0);ring.rotation.x=Math.PI/2;g.userData.healRing=ring;const halo=add(new T.TorusGeometry(.3,.025,6,24),blood,0,2.2,0);halo.rotation.x=Math.PI/2}
 let time=0;const update=base.update.bind(base);base.update=function(dt){time+=dt;update(dt);if(g.userData.healRing){g.userData.healRing.visible=this.pending==='heal'&&this.windup>0;g.userData.healRing.rotation.z=time*3}if(role==='gargoyle')g.position.y=.3+Math.sin(time*2)*.2;wings.forEach((w,i)=>{w.visible=role==='gargoyle'||this.phase===2;w.rotation.y=Math.sin(time*3)*(i?.25:-.25)});if(shield)shield.rotation.y=this.block>0?0:1.15;if(role==='captain'&&this.hp<=0)g.scale.y=.64};
 Object.assign(base,{id,role,chapterThree:true,chapterTwo:true,species:role==='baron'?'baron':role==='gargoyle'?'gargoyle':role==='hound'?'bloodhound':'order-enemy-'+role,name:{soldier:'Клинок барона',marksman:'Баронский стрелок',cantor:'Кровавый певчий',hound:'Кровавая гончая',gargoyle:'Каменная горгулья',knight:'Кровавый рыцарь',captain:'Начальник разведки Хаген',baron:'Барон Ротфельд'}[role],hp:C3_STATS[role].hp,maxHp:C3_STATS[role].hp,fixedLevel:C3_STATS[role].level,home:new T.Vector3(x,0,z),target:new T.Vector3(x,0,z),heading:0,generation:0,hit:false,aggro:null,timer:0,cooldown:1,windup:0,special:5,block:0,blockReady:4,pending:'normal',phase:1,addsUsed:false});return base;
}
